  "helpGuides.all": "모든 가이드",
  "helpGuides.content.credits.l1": "크레딧과 결제",
  "helpGuides.content.credits.l2": "환불 정책",
  "helpGuides.content.credits.s1.body": "이미지, 영상, 오디오, 음성 모두 같은 크레딧을 써요. 모든 모델은 생성하기 전에 가격을 보여 줘요.",
  "helpGuides.content.credits.s1.title": "모든 것에 잔액 하나",
  "helpGuides.content.credits.s2.body": "가입 시 받는 크레딧 10개가 먼저 사용되고, 쓰지 않으면 지급 후 90일이 지나 만료돼요.",
  "helpGuides.content.credits.s2.title": "무료 크레딧",
  "helpGuides.content.credits.s3.body": "크레딧 팩은 Credits 페이지에서 Stripe로 결제해 구매해요. 구매한 크레딧은 만료되지 않아요.",
  "helpGuides.content.credits.s3.title": "크레딧 구매",
  "helpGuides.content.credits.s4.body": "생성에 실패하면 크레딧이 자동으로 잔액에 돌아와요. Library에서 실패한 생성과 환불 내역을 볼 수 있어요.",
  "helpGuides.content.credits.s4.title": "실패했을 때",
  "helpGuides.content.credits.s5.body": "계정 하나로 1분에 생성을 10번까지 시작할 수 있어요. 이를 넘기면 요금이 차감되지 않고 요청이 거절돼요.",
  "helpGuides.content.credits.s5.title": "한도",
  "helpGuides.content.credits.summary": "잔액 하나, 가격은 미리 표시, 환불은 자동.",
  "helpGuides.content.credits.title": "크레딧과 환불 방식",
  "helpGuides.content.first-generation.l1": "스튜디오 열기",
  "helpGuides.content.first-generation.l2": "모든 가격 보기",
  "helpGuides.content.first-generation.s1.body": "Create로 이동하세요. 먼저 Sign in 하거나 계정을 만드세요. 새 계정은 이메일을 확인하면 무료 크레딧 10개를 한 번 받아요.",
  "helpGuides.content.first-generation.s1.title": "스튜디오 열기",
  "helpGuides.content.first-generation.s2.body": "오른쪽 목록에 모든 모델이 크레딧 가격과 함께 보여요. 이미지, 영상, 오디오 모델 모두 같은 잔액에서 차감돼요.",
  "helpGuides.content.first-generation.s2.title": "모델 고르기",
  "helpGuides.content.first-generation.s3.body": "보고 싶은 장면을 설명하세요. 영상이라면 무엇이 움직이는지, 카메라가 어떻게 움직이는지도 적어 주세요.",
  "helpGuides.content.first-generation.s3.title": "프롬프트 쓰기",
  "helpGuides.content.first-generation.s4.body": "Generate 버튼을 누르기 전에 버튼 위에 총액이 보여요. 10초 영상은 5초 영상의 두 배이고, 이미지를 여러 장 고르면 가격에 장수가 곱해져요.",
  "helpGuides.content.first-generation.s4.title": "비용 확인하기",
  "helpGuides.content.first-generation.s5.body": "크레딧은 Generate를 누를 때 차감돼요. 생성에 실패하면 크레딧이 자동으로 잔액에 돌아와요.",
  "helpGuides.content.first-generation.s5.title": "생성",
  "helpGuides.content.first-generation.summary": "모델을 고르고, 가격을 확인하고, 생성하세요.",
  "helpGuides.content.first-generation.title": "첫 이미지나 영상 만들기",
  "helpGuides.content.library.l1": "Library 열기",
  "helpGuides.content.library.s1.body": "실패한 작업을 포함해 모든 생성이 목록에 나와요. 무엇이 환불됐는지도 확인할 수 있어요.",
  "helpGuides.content.library.s1.title": "Library 열기",
  "helpGuides.content.library.s2.body": "상태와 유형(이미지, 영상, 오디오)으로 거르고, 그리드와 목록 보기를 전환할 수 있어요.",
  "helpGuides.content.library.s2.title": "걸러 보기",
  "helpGuides.content.library.s3.body": "카드의 별표를 누르면 Favourites에 추가돼요. Favourites는 별표를 단 그 브라우저에만 기억돼요.",
  "helpGuides.content.library.s3.title": "즐겨찾기에 별표 달기",
  "helpGuides.content.library.s4.body": "생성된 파일은 영구 보관되지 않아요. 각 카드에 파일이 보관되는 기간이 나와 있으니, 필요한 것은 그 전에 다운로드하세요.",
  "helpGuides.content.library.s4.title": "보관할 것은 다운로드하기",
  "helpGuides.content.library.summary": "Library에서 걸러 보고, 별표를 달고, 다운로드하세요.",
  "helpGuides.content.library.title": "만든 결과물 찾고 보관하기",
  "helpGuides.content.templates.l1": "템플릿 둘러보기",
  "helpGuides.content.templates.s1.body": "카테고리로 걸러 보세요. 각 카드에 사용하는 모델과 가격이 보여요.",
  "helpGuides.content.templates.s1.title": "템플릿 둘러보기",
  "helpGuides.content.templates.s2.body": "템플릿 페이지에서 전체 프롬프트와 비용을 볼 수 있어요. 모델에 필요하다면 업로드해야 할 파일도 알려 줘요.",
  "helpGuides.content.templates.s2.title": "하나 열기",
  "helpGuides.content.templates.s3.body": "Use this template을 누르면 프롬프트, 모델, 화면 비율이 채워진 스튜디오가 열려요. Generate를 누르기 전에는 아무것도 차감되지 않아요.",
  "helpGuides.content.templates.s3.title": "사용하기",
  "helpGuides.content.templates.s4.body": "생성하기 전에 프롬프트를 고치세요. 템플릿은 정해진 레시피가 아니라 출발점이에요.",
  "helpGuides.content.templates.s4.title": "내 것으로 만들기",
  "helpGuides.content.templates.summary": "프롬프트, 모델, 화면 비율이 준비된 상태로 한 번에 시작하세요.",
  "helpGuides.content.templates.title": "템플릿으로 시작하기",
  "helpGuides.content.your-own-files.l1": "도구 보기",
  "helpGuides.content.your-own-files.l2": "허용 가능한 사용",
  "helpGuides.content.your-own-files.s1.body": "Tools 페이지에서 내 파일로 시작하는 모든 모델과 필요한 입력, 비용을 볼 수 있어요.",
  "helpGuides.content.your-own-files.s1.title": "도구 고르기",
  "helpGuides.content.your-own-files.s2.body": "이미지는 PNG, JPEG, WebP로 20 MB까지예요. 영상은 MP4로 100 MB까지, 음성은 MP3 또는 WAV로 20 MB까지예요.",
  "helpGuides.content.your-own-files.s2.title": "파일 추가하기",
  "helpGuides.content.your-own-files.s3.body": "이미지는 From library로 이미 생성한 이미지를 다시 업로드하지 않고 고를 수 있어요.",
  "helpGuides.content.your-own-files.s3.title": "또는 결과물 다시 쓰기",
  "helpGuides.content.your-own-files.s4.body": "파일을 직접 소유하고 있거나 파일에 나오는 모든 사람의 허락을 받았다는 항목에 체크하세요. 이 확인은 생성 기록과 함께 저장돼요.",
  "helpGuides.content.your-own-files.s4.title": "사용 권한 확인하기",
  "helpGuides.content.your-own-files.s5.body": "가격과 실패 시 환불은 다른 생성과 똑같이 적용돼요.",
  "helpGuides.content.your-own-files.s5.title": "생성",
  "helpGuides.content.your-own-files.summary": "이미 가진 파일을 업스케일, 누끼 따기, 확장, 편집, 애니메이션, 립싱크로 다뤄 보세요.",
  "helpGuides.content.your-own-files.title": "내 이미지나 영상으로 작업하기",
  "helpGuides.lead": "만들기, 작업 보관, 크레딧 사용에 관한 간단한 안내입니다.",
  "helpGuides.links": "다음으로 이동할 곳",
